// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_equivRedmptVal", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("equivRedmptVal"))); } },
        { childId: "ipt_defrMms", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("defrMms"))); } },
        { childId: "ipt_splitRedmptCnt", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("splitRedmptCnt"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        (($c.util.getComponent('txt_amtStr') && $c.util.getComponent('txt_amtStr').setValue) ? $c.util.getComponent('txt_amtStr').setValue($c.num.formatNumberKor(String(((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).getValue) ? ($("#ipt_equivRedmptVal")[0]).getValue() : (((($("#ipt_equivRedmptVal")[0]) && typeof ($("#ipt_equivRedmptVal")[0]).val === 'function') ? ($("#ipt_equivRedmptVal")[0]).val() : ((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).value !== undefined) ? ($("#ipt_equivRedmptVal")[0]).value : ($("#ipt_equivRedmptVal")[0]))))) == null ? '' : ((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).getValue) ? ($("#ipt_equivRedmptVal")[0]).getValue() : (((($("#ipt_equivRedmptVal")[0]) && typeof ($("#ipt_equivRedmptVal")[0]).val === 'function') ? ($("#ipt_equivRedmptVal")[0]).val() : ((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).value !== undefined) ? ($("#ipt_equivRedmptVal")[0]).value : ($("#ipt_equivRedmptVal")[0])))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'amt_str'));
        $c.num.formatNumber($("#ipt_equivRedmptVal")[0]);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10106.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldinf10106: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf10106.onpageload' });
    }
};


