/**
 * @method
 * @name scwin.sendForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm
 * @returns
 * @hidden N
*/
scwin.sendForm = async function (fm) {
    /* sdd-asis-lifecycle:begin sendForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const defer_trm_int = "";
    if ($c.str.getByteLength($c.util.getComponent('ipt_equivRedmptVal').getValue()) == 0) {
        await $c.win.alert("균등상환액을 입력하세요.");
        $c.util.getComponent("ipt_equivRedmptVal").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_defrMms').getValue()) == 0) {
        await $c.win.alert("거치기간을 입력하세요.");
        $c.util.getComponent("ipt_defrMms").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_redmptPdIntTpCd').getValue()) == 0) {
        await $c.win.alert("거치기간이자를 선택하세요.");
        document.redmpt_pd_int_tp_cd.focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_splitRedmptCnt').getValue()) == 0) {
        await $c.win.alert("분할상환 횟수를 입력하세요.");
        $c.util.getComponent("ipt_splitRedmptCnt").focus();
        return;
    }
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("ipt_equivRedmptVal")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_equivRedmptVal').getValue());
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("ipt_defrMms")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_defrMms').getValue());
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("slc_redmptPdIntTpCd")) || { setValue: function () {} }).setValue($c.util.getComponent('slc_redmptPdIntTpCd').getValue());
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("ipt_splitRedmptCnt")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_splitRedmptCnt').getValue());
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.sendCancel
